"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Icon } from "@/components/ui/icon";
import * as Primitive from "@radix-ui/react-collapsible";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
export const collapsibleVariants = cva("v-collapsible");
export type CollapsibleProps = React.ComponentProps<typeof Primitive.Root>;
export function Collapsible({ className, ...props }: CollapsibleProps) {
  return (
    <Primitive.Root
      data-slot="collapsible"
      data-part="root"
      className={cn(collapsibleVariants(), className)}
      {...props}
    />
  );
}
export type CollapsibleTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function CollapsibleTrigger({
  className,
  children,
  ...props
}: CollapsibleTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="collapsible-trigger"
      data-part="trigger"
      className={cn(
        "inline-flex items-center gap-1.5 h-8 text-[length:var(--fs-control)] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    >
      {children}
    </Primitive.Trigger>
  );
}
export type CollapsibleContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function CollapsibleContent({
  className,
  ref,
  ...props
}: CollapsibleContentProps) {
  const contentRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => contentRef.current!);
  const morphRef = useMorph<HTMLDivElement>("cards", contentRef);
  const flowRef = useFlowAppearance<HTMLDivElement>(true, morphRef, "enter");
  React.useEffect(() => {
    const content = contentRef.current;
    // Radix temporarily disables CSS while measuring. Release that override so
    // its Presence can observe the shared nonvisual exit sentinel on close.
    if (content?.dataset.state === "open" && content.style.animationName === "none") {
      content.style.animationName = props.style?.animationName ?? "";
    }
  }, [props.style?.animationName]);
  return (
    <Primitive.Content
      ref={flowRef}
      data-slot="collapsible-content"
      data-part="content"
      className={cn(
        "v-collapsible__body mt-[var(--s-2)] py-[var(--s-3)] px-[var(--s-4)] bg-[var(--card)] rounded-[var(--r-md)] text-[13px]",
        className,
      )}
      {...props}
    />
  );
}
export type CollapsibleIndicatorProps = React.ComponentProps<"svg">;
export function CollapsibleIndicator({
  className,
  ...props
}: CollapsibleIndicatorProps) {
  return (
    <Icon
      name="chevron-down"
      data-slot="collapsible-indicator"
      data-part="indicator"
      aria-hidden="true"
      viewBox="0 0 24 24"
      className={cn("v-icon v-chev", className)}
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-collapsible:where([data-slot="collapsible"], [data-slot^="collapsible-"])
  [data-slot="collapsible-trigger"] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  list-style: none;
  cursor: pointer;
  font-size: var(--fs-control);
  color: var(--muted-foreground);
  height: 32px;
}
.v-collapsible:where([data-slot="collapsible"], [data-slot^="collapsible-"])
  [data-slot="collapsible-trigger"]::-webkit-details-marker {
  display: none;
}
.v-collapsible:where(
    [data-slot="collapsible"],
    [data-slot^="collapsible-"]
  )[data-state="open"]
  [data-slot="collapsible-trigger"]
  .v-chev {
  transform: rotate(180deg);
}
.v-collapsible__body:where(
  [data-slot="collapsible"],
  [data-slot^="collapsible-"]
) {
  margin-top: var(--s-2);
  padding: var(--s-3) var(--s-4);
  background: var(--card);
  border-radius: var(--r-md);
  font-size: 13px;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="collapsible"],
  [data-slot^="collapsible-"],
  [data-slot="collapsible"]::before,
  [data-slot="collapsible"]::after,
  [data-slot^="collapsible-"]::before,
  [data-slot^="collapsible-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="collapsible-content"][data-flow-presence][data-state="open"] { animation:none; }
[data-slot="collapsible-content"][data-state="closed"] { pointer-events:none; }
[data-slot="collapsible-trigger"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

}
